/**
 * Portal copy, English + Simplified Chinese.
 *
 * Shape rules, so this stays reviewable as it grows past the shell:
 *
 * - Group by SURFACE (`nav`, `shell`, `agencyHome`, …), not by page file. Two
 *   pages showing the same label must share the key, or the same word drifts
 *   into two translations.
 * - Every key present in `en` must be present in `zh`. `PortalTranslations` is
 *   derived from the English object, so a missing Chinese key is a TYPE ERROR
 *   rather than an `undefined` rendered into a portal.
 * - Money, dates and counts are NOT in here. They are formatted by
 *   `Intl.NumberFormat` / the existing date helpers against the active locale —
 *   a translated string that baked in "RM" would be a second source of truth
 *   for currency.
 * - "PR" stays "PR" in both. It is the product's term for the role, it appears
 *   on every screen and in the DB, and translating it on the UI only would make
 *   the portal and the data disagree.
 */

